SELECT Site.numsit,Site.nomsit,Site.typsit,Site.vilsit,Intervention.datint,Intervention.intfactok,Intervention.codpan,Intervention.typint,Intervention.mntfac,Intervention.numint,Intervention.numdev,parametre.datdeb,parametre.datfin,Client.nomcli FROM [Client],[Site],[parametre],[Intervention] WHERE (((Intervention.datint) Between parametre!datdeb And parametre!datfin) And ((Intervention.intfactok)=True)) ORDER BY Site.nomsit
